	private static double metric(PackedCostingTrace trace, int eventId, String name) {
		for (int ordinal = 0; ordinal < trace.doubleMetricCount(eventId); ordinal++) {
			if (name.equals(trace.doubleMetricName(eventId, ordinal))) {
				return trace.doubleMetricValue(eventId, ordinal);
			}
		}
		return Double.NaN;
	}

	private static boolean finiteNonNegative(double value) {
		return Double.isFinite(value) && value >= 0.0d;
	}

	private static double shifted(double value, double delta) {
		if (delta > 0.0d && value > Double.MAX_VALUE - delta) {
			return Double.MAX_VALUE;
		}
		return Math.max(0.0d, value + delta);
	}

	private static long mix(long hash, long value) {
		hash ^= value;
		return hash * 0x100000001b3L;
	}

	private static long nonzero(long value) {
		return value == 0L ? 1L : value;
	}

	private static long saturatedAdd(long left, long right) {
		return right > Long.MAX_VALUE - left ? Long.MAX_VALUE : left + right;
	}

